    if a is NSNull, b is NSNull { return true }
    if let aArr = a as? [Any], let bArr = b as? [Any] {
        guard aArr.count == bArr.count else { return false }
        for i in 0..<aArr.count where !jsonEqual(aArr[i], bArr[i]) { return false }
        return true
    }
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        guard Set(aDict.keys) == Set(bDict.keys) else { return false }
        for key in aDict.keys {
            guard let bVal = bDict[key] else { return false }
            if !jsonEqual(aDict[key]!, bVal) { return false }
