function formatNumber(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const dotIndex = fixed.indexOf('.');
  let intStr: string;
  let fracStr: string;
  if (dotIndex === -1) {
    intStr = fixed;
    fracStr = '';
  } else {
    intStr = fixed.substring(0, dotIndex);
    fracStr = fixed.substring(dotIndex + 1);
  }
  let sign = '';
  if (intStr.charAt(0) === '-') {
    sign = '-';
    intStr = intStr.substring(1);
  }
  let grouped = '';
  for (let i = intStr.length - 1, count = 0; i >= 0; i--, count++) {
    if (count > 0 && count % 3 === 0) {
      grouped = ',' + grouped;
    }
    grouped = intStr.charAt(i) + grouped;
  }
  if (decimals > 0) {
    return sign + grouped + '.' + fracStr;
  }
  return sign + grouped;
}

