fn format_integer(n: i64) -> String {
    let s = n.to_string();
    let negative = s.starts_with('-');
    let digits = if negative { &s[1..] } else { s.as_str() };
    let len = digits.len();
    let mut out = String::new();
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    if negative {
        out.insert(0, '-');
    }
    out
}

fn format_decimal(n: f64) -> String {
    let s = format!("{:.2}", n);
    let (int_part, dec_part) = match s.split_once('.') {
        Some((a, b)) => (a, b),
        None => (s.as_str(), "00"),
    };
    let negative = int_part.starts_with('-');
    let digits = if negative { &int_part[1..] } else { int_part };
    let len = digits.len();
    let mut out = String::new();
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    if negative {
        out.insert(0, '-');
    }
    format!("{}.{}", out, dec_part)
}

