static char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

typedef struct { char *name; long count; } LevelCount;
typedef struct { char *name; long count; } CompCount;
typedef struct { char *message; } Msg;

static int cmp_level(const void *a, const void *b) {
    return strcmp(((const LevelCount *)a)->name, ((const LevelCount *)b)->name);
}
static int cmp_comp(const void *a, const void *b) {
    return strcmp(((const CompCount *)a)->name, ((const CompCount *)b)->name);
}
static int cmp_msg(const void *a, const void *b) {
    return strcmp(((const Msg *)a)->message, ((const Msg *)b)->message);
}

static void add_level(LevelCount **arr, size_t *cnt, size_t *cap, const char *name) {
    for (size_t i = 0; i < *cnt; i++) {
        if (strcmp((*arr)[i].name, name) == 0) { (*arr)[i].count++; return; }
    }
    if (*cnt == *cap) {
        *cap = *cap ? *cap * 2 : 16;
        *arr = realloc(*arr, *cap * sizeof(LevelCount));
    }
    (*arr)[*cnt].name = my_strdup(name);
    (*arr)[*cnt].count = 1;
    (*cnt)++;
}

static void add_comp(CompCount **arr, size_t *cnt, size_t *cap, const char *name) {
    for (size_t i = 0; i < *cnt; i++) {
        if (strcmp((*arr)[i].name, name) == 0) { (*arr)[i].count++; return; }
    }
    if (*cnt == *cap) {
        *cap = *cap ? *cap * 2 : 16;
        *arr = realloc(*arr, *cap * sizeof(CompCount));
    }
    (*arr)[*cnt].name = my_strdup(name);
    (*arr)[*cnt].count = 1;
    (*cnt)++;
}

static void add_msg(Msg **arr, size_t *cnt, size_t *cap, const char *msg) {
    for (size_t i = 0; i < *cnt; i++) {
        if (strcmp((*arr)[i].message, msg) == 0) return;
    }
    if (*cnt == *cap) {
        *cap = *cap ? *cap * 2 : 16;
        *arr = realloc(*arr, *cap * sizeof(Msg));
    }
    (*arr)[*cnt].message = my_strdup(msg);
    (*cnt)++;
}

