        if let JsonValue::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }
    fn as_f64(&self) -> Option<f64> {
        if let JsonValue::Number(n) = self {
