let filePath = "__FIXTURE_DIR__/graph.json"
let data = try Data(contentsOf: URL(fileURLWithPath: filePath))

struct Edge: Codable {
    let from: String
    let to: String
    let weight: Double
}

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

let graph = try JSONDecoder().decode(GraphData.self, from: data)

// Build undirected adjacency list
var adjacency: [String: [(node: String, weight: Double)]] = [:]
for node in graph.nodes {
    adjacency[node] = []
}
for edge in graph.edges {
    adjacency[edge.from]?.append((edge.to, edge.weight))
    adjacency[edge.to]?.append((edge.from, edge.weight))
}

// Dijkstra's algorithm from node "A"
var dist: [String: Double] = [:]
for node in graph.nodes {
    dist[node] = Double.infinity
}
dist["A"] = 0

var visited: Set<String> = []

while true {
    // Select the unvisited node with the smallest tentative distance
    var minNode: String? = nil
    var minDist = Double.infinity
    for node in graph.nodes {
        let d = dist[node] ?? Double.infinity
        if !visited.contains(node) && d < minDist {
            minDist = d
            minNode = node
        }
    }
    guard let current = minNode else { break }
    visited.insert(current)

    // Relax edges to neighbors
    for (neighbor, weight) in (adjacency[current] ?? []) {
        let newDist = dist[current]! + weight
        if newDist < (dist[neighbor] ?? Double.infinity) {
            dist[neighbor] = newDist
        }
    }
}

func formatDistance(_ d: Double) -> String {
    if d.isFinite && d == d.rounded() && abs(d) < 1e15 {
