static char *run_cmd(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    char chunk[1024];
    size_t n;
    while ((n = fread(chunk, 1, sizeof(chunk), fp)) > 0) {
        if (len + n + 1 > cap) {
            size_t newcap = (len + n + 1) * 2;
            char *nb = (char *)realloc(buf, newcap);
            if (!nb) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = nb;
            cap = newcap;
        }
        memcpy(buf + len, chunk, n);
        len += n;
    }
    buf[len] = '\0';
    pclose(fp);

    /* Strip trailing whitespace/newlines */
    while (len > 0) {
        char c = buf[len - 1];
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t' ||
            c == '\v' || c == '\f') {
            buf[--len] = '\0';
        } else {
            break;
        }
    }

    return buf;
}

