            printf("%4d", m[i][j]);
        }
        printf("\n");
    }
}

int main(void) {
    int A[N][N] = {{1,2,3},{4,5,6},{7,8,9}};
    int B[N][N] = {{9,8,7},{6,5,4},{3,2,1}};
    int C[N][N] = {{0}};

    /* C = A x B */
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int sum = 0;
            for (int k = 0; k < N; k++) {
                sum += A[i][k] * B[k][j];
            }
            C[i][j] = sum;
        }
    }

    /* Determinant of 3x3 matrix C */
    long det = 0;
    det = (long)C[0][0] * ((long)C[1][1] * C[2][2] - (long)C[1][2] * C[2][1])
        - (long)C[0][1] * ((long)C[1][0] * C[2][2] - (long)C[1][2] * C[2][0])
        + (long)C[0][2] * ((long)C[1][0] * C[2][1] - (long)C[1][1] * C[2][0]);

    printf("=== Matrix Operations ===\n\n");

    printf("Matrix A:\n");
    print_matrix(A);
    printf("\n");

    printf("Matrix B:\n");
    print_matrix(B);
    printf("\n");

    printf("A x B =\n");
    print_matrix(C);
    printf("\n");

    printf("Determinant: %ld\n", det);

    return 0;
}

